constraint.cypher:
MATCH (t:Type)-[:DECLARES]->(m:Method:Endpoint)-[:HAS]->(p:Parameter)-[:ANNOTATED_BY]->(:Annotation)-[:OF_TYPE]->(:Type {fqn: 'org.springframework.web.bind.annotation.RequestBody'})
    WHERE NOT t:Test AND NOT EXISTS { MATCH (p)-[:ANNOTATED_BY]->(:Annotation)-[:OF_TYPE]->(vt:Type) WHERE vt.fqn IN ['jakarta.validation.Valid', 'javax.validation.Valid', 'org.springframework.validation.annotation.Validated'] }
    RETURN DISTINCT m AS Element, t.fqn AS Fqn, m.signature AS Detail
